def _dist(u, v):
    # Parent of i is i//2 (and i//2 < i), so the larger label is never an
    # ancestor of the smaller one unless equal; move the larger up until equal.
    d = 0
    while u != v:
        if u > v:
            u //= 2
        else:
            v //= 2
        d += 1
    return d

