from hypothesis import strategies as st

@st.composite
def gen(draw):
    T = draw(st.integers(1, 5))
    lines = [str(T)]
    for _ in range(T):
        N = draw(st.one_of(st.integers(1, 6), st.integers(1, 40)))
        X = draw(st.one_of(st.just(1), st.just(N), st.integers(1, N)))
        K = draw(st.one_of(st.just(0), st.just(N - 1), st.integers(0, N - 1)))
        lines.append(f"{N} {X} {K}")
    return "\n".join(lines) + "\n"

def validate(inp):
    t = inp.split()
    if not t:
        return False
    try:
        T = int(t[0])
    except ValueError:
        return False
    if not (1 <= T <= 10**5):
        return False
    if len(t) != 1 + 3 * T:
        return False
    for i in range(T):
        try:
            N = int(t[1 + 3 * i])
            X = int(t[2 + 3 * i])
            K = int(t[3 + 3 * i])
        except ValueError:
            return False
        if not (1 <= N <= 10**18):
            return False
        if not (1 <= X <= N):
            return False
        if not (0 <= K <= N - 1):
            return False
    return True

def ref(inp):
    t = inp.split()
    T = int(t[0])
    out = []
    for i in range(T):
        N = int(t[1 + 3 * i])
        X = int(t[2 + 3 * i])
        K = int(t[3 + 3 * i])
        # Level-by-level BFS on the implicit tree: neighbors of v are v//2 (if v>=2), 2v, 2v+1 (if <= N).
        visited = {X}
        frontier = [X]
        for _ in range(K):
            new = []
            for v in frontier:
                nbrs = []
                if v >= 2:
                    nbrs.append(v // 2)
                nbrs.append(2 * v)
                nbrs.append(2 * v + 1)
                for w in nbrs:
                    if w <= N and w not in visited:
                        visited.add(w)
                        new.append(w)
            frontier = new
        out.append(str(len(frontier)))
    return "\n".join(out) + "\n"
